import { Card, Stack, CircularProgress, Dropdown, Menu, MenuButton, MenuItem, Button, Typography, Tooltip, CardContent, CardActions } from '@mui/joy';
import DecayGraph from './Graph';
import List from '@mui/joy/List';
import ListItem from '@mui/joy/ListItem';
import { VariableSizeList } from 'react-window';
import { useSelector, useDispatch } from 'react-redux'
import { useState, useEffect } from 'react';
import FilterBar from './FilterBar';
import { API_PATH } from '../Internal/api.js';


export default function TreeList() {

    const [containerHeight, setContainerHeight] = useState(window.innerHeight * 0.7); // Default to 70vh
    // use not the window, but the current context size
    
    const [filter, setFilter] = useState({});
    const [filterReady, setFilterReady] = useState(false);
    const [filteredTopologies, setFilteredTopologies] = useState([]);
    const mainGraph = useSelector((state) => state.mainGraph);
    const n = useSelector((state) => state.decay);
    const globalIsobars = useSelector((state) => state.intermediateState.isobars);
    const checkedGraphs = useSelector((state) =>state.checkedGraphs);
    const [dropdownOpen, setDropdownOpen] = useState(false);
    useEffect(() => {
        // Recalculate height on window resize
        const handleResize = () => {
            setContainerHeight(window.innerHeight * 0.7); // Update height dynamically
        };

        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    useEffect(() => {
        setFilterReady(false);
        setFilter({});
        setFilteredTopologies([]);
    }, [n]);

    const graphs = useSelector((state) => state.graph);
    

    const dispatch = useDispatch();
    const handleGraphCardClick = (tuple) => {
        if (! dropdownOpen) {
            dispatch({ type: 'SET_MAIN_GRAPH', payload: tuple });
        }
    };

    if (!graphs.hasOwnProperty('topologies')) {
        return (
            <List>
            </List>
        );
    }
    if (!filterReady && !(Object.keys(filter).length === 0)) {
        return (
            <CircularProgress />
        )
    }




    const ChangeFilter = ( filter ) => {
        setFilter(filter);
        setFilterReady(false);

        const filterString = "[" + Object.keys(filter).map((key) => {
            return key;
        }).join(",") + "]";
        const api_query = API_PATH + "filtered?n="+ n + "&filter=" + filterString;
        fetch(api_query)
        .then(response => {
            if (!response.ok) {
            throw new Error('Network response was not ok');
            }
            return response.json();
        })
        .then(data => {
            setFilteredTopologies(data.topologies);
            setFilterReady(true);
        })
        .catch(error => {
            console.error('Error:', error);
        });
    }

    const items = filterReady ? filteredTopologies : graphs.topologies;

    const buttonComponent = ({index}) => {
        const tuple = items[index];
        return (
            <Card variant={(mainGraph.tuple == items[index]) ? 'soft' : 'outlined'}  sx={{
                width: '100%', // Ensures the Card takes up full button width
                border: (mainGraph.tuple == items[index]) ? '4px solid #ccc' : '1px solid #ccc', // Optional: for visualization
                height: '100%', // Ensures the Card takes up full button height
              }}>
                <CardContent>
            <Button onClick={() => {
                handleGraphCardClick(items[index])
                dispatch({ type: 'SET_TREE_MASK', payload: {} });
            }
            } color={(mainGraph.tuple == items[index]) ? null : null} height={"100%"}>
                <DecayGraph tuple={tuple} />
            </Button>
            </CardContent>
            <CardActions>
            {ChainInfo({index})}
            </CardActions>
            </Card>
        )
    }

    const ChainInfo = ({index}) => {
        const tuple = items[index];
        const isobars = {};
        const extractIsobars = (topology) => {
            if (Array.isArray(topology)) {
                const flatTopology = topology.flat(Infinity).sort();
                const topologyString = JSON.stringify(flatTopology);
                isobars[topologyString] = {resonances: {}, label: topologyString, tuple: flatTopology};
                topology.forEach((subTopology) => {
                    extractIsobars(subTopology);
                });
            }
        };
        extractIsobars(tuple[0]);
        extractIsobars(tuple[1]);
        const completeChains = Object.keys(isobars).map((isobar) => {
            return Object.keys(globalIsobars[isobar].resonances).length;
        });

        // check for any number not 0 in completeChains

        // const anyNonZero = completeChains.reduce((prev, curr) => (curr != 0) || prev, false);
        const totalChains = completeChains.reduce((prev, curr) => curr * prev, 1);
        
        // var stateColor = (anyNonZero && totalChains === 0) ? 'warning' : 'neutral';
        var stateColor = 'neutral';
        const relatedTrees = ((checkedGraphs.hasOwnProperty("trees")) ?
            checkedGraphs.trees.filter(tree => tree.topology == JSON.stringify(items[index])) : []);

            
        if (relatedTrees.length > 0) {
            if ( relatedTrees.every(tree => tree.check) ){
                stateColor = 'success';
            }
            else if ( relatedTrees.some(tree => tree.check) ){
                stateColor = 'warning';
            }
            else if ( relatedTrees.every(tree => !tree.check) ){
                stateColor = 'danger';
            }
        }
        
        console.log(relatedTrees);

        return (
            <Dropdown onOpen={() => setDropdownOpen(!dropdownOpen)}>
                <MenuButton color={stateColor}>
                    Number of complete Chains: {totalChains}
                </MenuButton>
                <Menu>
                    {
                        relatedTrees.map((tree, ind) => (
                            <Tooltip title={tree.check ? "All Good" : "Decays marked in red are not possible with given P and J values"} >
                                <MenuItem key={ind}>
                                <Button onClick={
                                            () => {
                                                dispatch({ type: 'SET_TREE_MASK', payload: tree.resonances });
                                                handleGraphCardClick(items[index]);
                                                console.log(tree.resonances);
                                            }
                                        } color={null}
                                        >
                                    {Object.keys(tree.resonances).map((resonanceKey, resIndex) => (
                                            <Typography 
                                                key={resIndex}
                                                // color ={tree.check ? 'success' : 'danger'}
                                                color={tree.failed.find((element) => element == resonanceKey) == resonanceKey ? 'danger' : 'success'}
                                            >
                                                {tree.resonances[resonanceKey].name + (resIndex < (Object.keys(tree.resonances).length - 1) ? ", " : "")}
                                            </Typography>
                                    ))}
                                </Button>
                                </MenuItem>
                            </Tooltip>
                        ))
                    }
                    
                </Menu>
            </Dropdown>
        )
    };
    

    const Row = ({ index, style }) => (
        <ListItem style={{...style}} >

            {/* <Stack direction="column" spacing={-6} > */}
            {/* <ListItemButton onClick={() => handleGraphCardClick(items[index])}   > */}
            {/* <Card variant={(mainGraph.tuple == items[index]) ? 'solid' : 'outlined'}>
                <DecayGraph tuple={items[index]} />
            </Card> */}
            {buttonComponent({index})}
            {/* </ListItemButton> */}
            {/* {ChainInfo({index})} */}
            {/* </Stack> */}

         </ListItem>
    );

    const getSize = (index) => {
        // Return the height of each item based on its index
        const tuple = items[index];

        const findMultiVertex = (topology) => {
            if (Array.isArray(topology)) {
                if (Array.isArray(topology[0]) && Array.isArray(topology[1])) {
                    return true;
                }
                return findMultiVertex(topology[0]) || findMultiVertex(topology[1]);
            }
            return false;
        };
        const isLarge = findMultiVertex(tuple);
        return isLarge ? 300 : 250;
    };

    return (
        <div style={{ maxHeight: '100%', maxWidth: '100%', overflowY: 'hidden'}}> 
        <Stack direction="column" spacing={2}>
            <FilterBar setFilter={ChangeFilter} filter={filter} />
        <List sx={{
            // maxHeight: '100vh', // Set a fixed height for the list
            overflowY: 'auto', // Enable vertical scrolling
            // border: '1px solid #ccc', // Optional: for visualization
            // padding: '1rem', // Optional: for styling
            // width: '300px', // Optional: set a fixed width for the list
          }}>
            <VariableSizeList
                height={containerHeight} // Total height of the list container
                itemCount={items.length} // Total items
                itemSize={(ind) => getSize(ind)} // Height of each item
                maxWidth="100%" // Match List width
            >
            {
                Row
            }
            </VariableSizeList>
            </List>
        </Stack>
        </div>

    );
    }